const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometry for Antakya, Hatay Province, Turkey
  const antakya = ee.Geometry.Point([36.1497, 36.2066]).buffer(5000); // 5km buffer around city center

  // Define the two dates
  const date1 = '2023-02-21';
  const date2 = '2023-04-30';

  // Get VIIRS DNB daily data
  const viirsCol = ee.ImageCollection('NOAA/VIIRS/001/VNP46A2')
    .select('DNB_BRDF_Corrected_NTL');

  // Filter for first date
  const img1 = viirsCol.filterDate(date1, ee.Date(date1).advance(1, 'day')).first();
  const img2 = viirsCol.filterDate(date2, ee.Date(date2).advance(1, 'day')).first();

  // Check if images exist
  const img1Exists = img1 ? true : false;
  const img2Exists = img2 ? true : false;

  if (!img1Exists || !img2Exists) {
    console.log(`Feb 21 image: ${img1Exists ? 'Yes' : 'No'}`);
    console.log(`Apr 30 image: ${img2Exists ? 'Yes' : 'No'}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // Get pixel counts and mean radiance values
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: antakya,
    scale: 500,
    maxPixels: 1e9
  });

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: antakya,
    scale: 500,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('DNB_BRDF_Corrected_NTL_mean').getInfo();
  const count1 = stats1.get('DNB_BRDF_Corrected_NTL_count').getInfo();
  const mean2 = stats2.get('DNB_BRDF_Corrected_NTL_mean').getInfo();
  const count2 = stats2.get('DNB_BRDF_Corrected_NTL_count').getInfo();

  // Check for valid pixels
  if (count1 === 0 || count2 === 0) {
    console.log(`Feb 21 pixels: ${count1}, Apr 30 pixels: ${count2}`);
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log(`Feb 21 mean: ${mean1}, Apr 30 mean: ${mean2}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare the values
  console.log(`Feb 21: ${mean1.toFixed(4)} (${count1} px)`);
  console.log(`Apr 30: ${mean2.toFixed(4)} (${count2} px)`);

  if (mean1 > mean2) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
